<div class="row"><div class="col-md-7"><div class="box box-primary"><div class="box-header"><h3 class="box-title">Tambah perusahaan / kapal</h3></div><div class="box-body"><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><label>Area</label><select name="SpbbID" class="form-control" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['SpbbID'] ?>"><?= html_escape($b['SpbbName']) ?></option><?php endforeach; ?></select><div class="row">
<?php foreach(array('CompanyName'=>'Nama Perusahaan','VesselName'=>'Nama Kapal (opsional)','Address'=>'Alamat Perusahaan','Flag'=>'Bendera','GrossTonnage'=>'DWT / GT','VesselType'=>'Jenis Kapal','MainTank'=>'Kapasitas Tangki Utama','DailyTank'=>'Kapasitas Tangki Harian') as $key=>$label): ?><div class="col-sm-6 form-group"><label><?= $label ?></label><input class="form-control" name="<?= $key ?>" maxlength="<?= $key==='Address'?1000:($key==='CompanyName'||$key==='VesselName'?200:100) ?>" <?= $key==='CompanyName'?'required':'' ?> value="<?= $key==='Flag'?'Indonesia':'' ?>"></div><?php endforeach; ?></div><button class="btn btn-primary">Simpan</button></form></div></div></div>
<div class="col-md-5"><div class="box box-success"><div class="box-header"><h3 class="box-title">Import CSV</h3></div><div class="box-body"><p>Unduh template, isi data, lalu impor untuk satu area. Semua baris diperiksa dalam satu transaksi.</p><a href="?template=1" class="btn btn-default">Download Template CSV</a><form method="post" enctype="multipart/form-data"><?php $this->load->view('pipeline/billing_token'); ?><input type="hidden" name="action" value="import"><label>Area tujuan</label><select name="SpbbID" class="form-control" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['SpbbID'] ?>"><?= html_escape($b['SpbbName']) ?></option><?php endforeach; ?></select><div class="form-group"><label>CSV maksimal 2 MB</label><input type="file" name="ImportFile" accept=".csv,text/csv" required></div><button class="btn btn-success">Import</button></form></div></div></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Daftar Perusahaan</h3></div><div class="box-body table-responsive"><table class="table table-striped"><tr><th>Area</th><th>Perusahaan</th><th>Alamat</th></tr><?php foreach($companies as $r): ?><tr><td><?= (int)$r['SpbbID'] ?></td><td><?= html_escape($r['CompanyName']) ?></td><td><?= html_escape($r['Address']) ?></td></tr><?php endforeach; ?><?php if(!$companies): ?><tr><td colspan="3">Belum ada perusahaan. Tambahkan data atau import CSV.</td></tr><?php endif; ?></table></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Daftar Kapal</h3></div><div class="box-body table-responsive"><table class="table table-striped"><tr><th>Area</th><th>Kapal</th><th>Perusahaan</th><th>Bendera</th><th>DWT / GT</th><th>Jenis</th><th>Tangki Utama / Harian</th></tr><?php foreach($vessels as $r): ?><tr><td><?= (int)$r['SpbbID'] ?></td><?php foreach(array('VesselName','CompanyName','Flag','GrossTonnage','VesselType') as $k): ?><td><?= html_escape($r[$k]) ?></td><?php endforeach; ?><td><?= html_escape($r['MainTank'].' / '.$r['DailyTank']) ?></td></tr><?php endforeach; ?><?php if(!$vessels): ?><tr><td colspan="7">Belum ada kapal.</td></tr><?php endif; ?></table></div></div></section></div>